input.proposed_solution:
Replace the strict regex with a minimal plausibility check (an '@' with text on both sides, no whitespace) and rely on the confirmation email as the real validation. Tests cover the reported addresses and obvious typos.

Patch (already applied in the repository snapshot):
```diff
--- a/src/email.js
+++ b/src/email.js
@@ -1,6 +1,13 @@
 // @ts-check

-/** @param {string} email */
+/**
+ * Deliberately loose: one "@" with something on both sides and no whitespace.
+ * The address is proven by the confirmation email we send next; this check only catches typos
+ * like a missing "@". Strict regexes rejected real customers (uppercase, IDN domains, "+tags",
+ * new TLDs) - see the task context.
+ * @param {string} email
+ */
 export function isPlausibleEmail(email) {
-  return /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(email);
+  const at = email.lastIndexOf("@");
+  return at > 0 && at < email.length - 1 && !/\s/.test(email);
 }
--- a/test/email.test.js
+++ b/test/email.test.js
@@ -2,6 +2,10 @@
 import assert from "node:assert/strict";
 import { isPlausibleEmail } from "../src/email.js";

-test("accepts a normal address", () => {
-  assert.equal(isPlausibleEmail("ann@example.com"), true);
+test("accepts real-world addresses", () => {
+  for (const e of ["ann@example.com", "Ann.Lee@Example.COM", "a+tag@sub.example.co.uk", "josé@bücher.de", "x@localhost.dev", "o'brien@example.ie"]) assert.equal(isPlausibleEmail(e), true, e);
 });
+
+test("rejects obvious typos", () => {
+  for (const e of ["", "annexample.com", "@example.com", "ann@", "ann @example.com"]) assert.equal(isPlausibleEmail(e), false, e);
+});
```
